const FLOW_SECTIONS = [['journey', 'Journeys (03 §C.1–C.8, 01 §E.2)'], ['error', 'Error and recovery flows (03 §D)']];
function pageFlows() {
  return { title: 'Flows', route: '(03 §C journeys, §D error flows)', html: `<h1>Flows</h1><p class="lead">Clickable walkthroughs. Every step cites its spec section and shows the real screen in the state the spec describes. The frames are live: hold, drag, toggle.</p>${FLOW_SECTIONS.map(([k, t]) => `<h2>${t}</h2><div class="cards">${FLOWS.filter(f => f.kind === k).map(f => `<a class="card" href="#flow-${f.id}"><span class="code">${esc(f.cite)}</span><b style="display:block;font:500 15px var(--f-display);text-transform:uppercase;margin:3px 0">${esc(f.title)}</b><span style="font-size:12px;color:#A9B3BE">${f.steps.length} step${f.steps.length > 1 ? 's' : ''}</span></a>`).join('')}</div>`).join('')}`, mount() { } };
}
const FLOWST = { id: null, i: 0, fr: null, scr: null };
function pageFlow(id) {
  const f = FLOWS.find(x => x.id === id); if (!f) return { title: 'Flow', route: '', html: '<h1>Flow not found</h1>', mount() { } };
  FLOWST.id = id; FLOWST.i = 0; FLOWST.fr = null;
  return { title: f.title, route: '(flow)', html: `<a href="#flows" style="font-size:13px">← All flows</a><h1>${esc(f.title)}</h1><span class="code" style="color:#8592A0">${esc(f.cite)}</span><div class="two" style="margin-top:14px"><div id="fl-steps" class="col" style="gap:6px"></div><div id="fl-view" style="min-width:0"></div></div>`,
    mount(root) { const draw = () => { $('#fl-steps', root).innerHTML = f.steps.map((s, i) => `<button class="flowstep" data-fl="${i}" ${i === FLOWST.i ? 'aria-current="step"' : ''}><span class="n">${String(i + 1).padStart(2, '0')}</span><span><span style="font-size:13px">${esc(s.t)}</span><br><span class="cite">${esc(s.cite)} · ${s.scr} · ${esc((SCREENS[s.scr].states.find(x => x[0] === s.st) || [0, s.st])[1])}</span></span></button>`).join('') + `<div class="row" style="gap:8px;margin-top:6px"><button class="shellbtn" data-fl="prev">◀ PREV</button><button class="shellbtn" data-fl="next">NEXT ▶</button></div>`; show(); };
      const show = () => { const s = f.steps[FLOWST.i], host = $('#fl-view', root), S = SCREENS[s.scr]; if (FLOWST.fr && FLOWST.fr.screenId === s.scr && FLOWST.fr.devKey === s.dev && FLOWST.fr.el.isConnected) { FLOWST.fr.setState(s.st); return; } destroyFrames(host); host.innerHTML = fhost({ screen: s.scr, state: s.st, dev: s.dev, cell: true, noSwitcher: true }); mountHosts(host); FLOWST.fr = Object.values(FRAMES).find(x => x.el.isConnected && x.screenId === s.scr); fitAll(); };
      root.addEventListener('click', e => { const b = e.target.closest('[data-fl]'); if (!b) return; const a = b.dataset.fl; if (a === 'next') FLOWST.i = Math.min(f.steps.length - 1, FLOWST.i + 1); else if (a === 'prev') FLOWST.i = Math.max(0, FLOWST.i - 1); else FLOWST.i = +a; draw(); }); draw(); } };
}
